+require 'vendor/autoload.php';
+use Hyperf\Support\Fluent;
+
+enum Suit: string { case Hearts = 'hearts'; case Spades = 'spades'; }
+
+$f = new Fluent(['a' => ['b' => 1], 'num' => '42', 'flt' => '3.14', 'bool' => 'yes', 's' => 5]);
+
+// set dot
+$f->set('a.c', 2);
+var_dump($f->all()['a']);
+
+// fill
+$f->fill(['x' => 'y']);
+var_dump($f->all()['x']);
+
+// scope
+$s = $f->scope('a');
+var_dump($s instanceof Fluent, $s->all());
+$s2 = $f->scope('missing', ['d' => 9]);
+var_dump($s2->all());
+
+// typed
+var_dump((string) $f->string('s'), (string) $f->string('nope'));
+var_dump($f->boolean('bool'), $f->boolean('nope'));
+var_dump($f->integer('num'), $f->integer('nope'));
+var_dump($f->float('flt'), $f->float('nope'));
+var_dump($f->array('a'), $f->array(['num','flt']));
+var_dump($f->collect('a')->all());
+var_dump($f->date('nope'));
+
+$fe = new Fluent(['suit' => 'hearts', 'bad' => 'x', 'many' => ['hearts','nope','spades']]);
+var_dump($fe->enum('suit', Suit::class));
+var_dump($fe->enum('bad', Suit::class));
+var_dump($fe->enums('many', Suit::class));
+
+// macro
+Fluent::macro('sum', function () { return array_sum($this->all(['num'])); });
+$fm = new Fluent(['num' => 5]);
+var_dump($fm->sum());
+
+// date with format
+$fd = new Fluent(['d' => '2021-01-05']);
+var_dump($fd->date('d')->format('Y-m-d'));
+var_dump($fd->date('d', 'Y-m-d')->format('Y-m-d'));
+echo "OK\n";
